// Input:  { "currentDate": "2026-02-26T17:41:48.851+00:00" }
// Output: { "receivedAfter": "2026-02-26T17:31:48.851Z" }

const s = $input.first()?.json?.currentDate;

if (typeof s !== "string" || !s.trim()) {
  throw new Error("Missing `currentDate` (expected a string).");
}

const d = new Date(s);
if (Number.isNaN(d.getTime())) {
  throw new Error(`Invalid currentDate: ${s}`);
}

// subtract 10 minutes
const d2 = new Date(d.getTime() - 10 * 60 * 1000);

// Graph-native ISO UTC: YYYY-MM-DDTHH:mm:ss.sssZ
const isoUtc = d2.toISOString();

return [
  {
    json: {
      receivedAfter: isoUtc,
    },
  },
];

// ╔═══════════════════════════════════════════════════════════════════╗
// ║                                                                   ║
// ║   ██╗  ██╗ ██████╗ ██╗   ██╗███████╗███████╗                     ║
