  return String(s||'').toLowerCase().replace(/\s+/g,' ').replace(/[^\p{L}\p{N} ]/gu,'').trim();
}
function jaccardTokenSet(a,b) {
  const A = new Set(normalizeForMatch(a).split(' ').filter(Boolean));
  const B = new Set(normalizeForMatch(b).split(' ').filter(Boolean));
  if (!A.size || !B.size) return 0;
  let inter = 0; for (const t of A) if (B.has(t)) inter++;
  return inter / (A.size + B.size - inter);
}
function sha256(s){return crypto.createHash('sha256').update(s).digest('hex');}

// ---------- DATE PARSING (UK log preserved) ----------
function parseUkDate(str) {
  if (!str) return null;
  const m = String(str).match(/(\d{1,2})\s+([A-Za-z]{3,})\s+(\d{4})(?:[,\s]+(\d{1,2}):(\d{2}))?/);
  if (!m) return null;
  const d=+m[1], mo=MONTHS[m[2].slice(0,3).toLowerCase()], y=+m[3];
  const hh=m[4]?+m[4]:0, mm=m[5]?+m[5]:0;
  if (mo==null) return null;
  const utcGuess = Date.UTC(y,mo,d,hh,mm);
  const isBST = (() => {
    const lastSun = (yr,mon) => { const dt=new Date(Date.UTC(yr,mon+1,0)); return dt.getUTCDate() - dt.getUTCDay(); };
    const startBST = Date.UTC(y,2,lastSun(y,2),1,0);
    const endBST   = Date.UTC(y,9,lastSun(y,9),1,0);
    return utcGuess >= startBST && utcGuess < endBST;
  })();
  return new Date(utcGuess - (isBST?60:0)*60000);
}

// ---------- SENDER CLASSIFIERS ----------
const addrOf = s => String(s||'').toLowerCase().trim();
const isEnquiryFormSender = a => ENQUIRY_FORM_SENDERS.has(addrOf(a));
const isInternalSender    = a => /@spartancrew\.co\.uk$/i.test(addrOf(a)) || INTERNAL_SENDERS.has(addrOf(a));
const isAiSender          = a => addrOf(a) === AI_SEND_ADDRESS;

// ---------- THREAD PARSER ----------
function parseThreadHistory(raw) {
  if (!raw) return [];
  const blocks = String(raw).split(/---\s*Message\s+\d+\s+of\s+\d+\s*---/i).map(b=>b.trim()).filter(Boolean);
  const out = [];
  for (const b of blocks) {
    const fromM = b.match(/^From:\s*(.+)$/mi);
    const dateM = b.match(/^Date:\s*(.+)$/mi);
    const subjM = b.match(/^Subject:\s*(.+)$/mi);
    const headerEnd = b.search(/\n\s*\n/);
    const body = headerEnd>-1 ? b.slice(headerEnd).trim() : '';
    const fromRaw = fromM ? fromM[1].trim() : '';
    const emailM = fromRaw.match(/<([^>]+)>/) || fromRaw.match(/([\w.+-]+@[\w.-]+)/);
    const fromAddress = emailM ? emailM[1] : fromRaw;
    out.push({
      fromAddress: addrOf(fromAddress),
      fromRaw,
      date: parseUkDate(dateM?dateM[1]:''),
      dateRaw: dateM?dateM[1].trim():'',
      subject: subjM?subjM[1].trim():'',
      bodyHtml: body,
      bodyText: stripHtmlToText(body),
    });
  }
  return out;
}

// ================================================================
// SIGNATURE / EXIT-GREETING EXTRACTION
// ================================================================
// IMPORTANT: The regex scans BACKWARDS (last match wins) so that
// phrases like "Thank you for..." in the body are not mistaken
// for a sign-off. Do NOT change to a forward scan.
// ================================================================

const EXIT_GREETING_RE = /^[ \t]*(?:kind(?:est)?\s*regards|best\s*(?:wishes|regards)?|regards|sincerely|yours\s*(?:sincerely|faithfully|truly)|many\s*thanks|warm(?:est)?\s*(?:regards|wishes)?|cheers|with\s*(?:thanks|gratitude)|all\s*the\s*best|take\s*care|speak\s*soon|looking\s*forward|thanks\s*(?:again|so\s*much|very\s*much|in\s*advance)?|thank\s*you\s*(?:very\s*much|so\s*much|kindly|in\s*advance)?)[,.\s!]*$/im;

const SIG_NOISE_RE = /^(?:--|___|\*\*\*|===|~~~|sent\s+from|get\s+outlook|this\s+email\s+(?:was|is)|https?:\/\/|www\.|disclaimer|confidential|unsubscribe)/i;

const PHONE_RE = /(?:(?:Tel(?:ephone)?|Phone|Mobile|Mob|Cell|Direct|Office|Fax|M|T|P|O)\s*[:.]\s*)?([+\d][\d\s().-]{5,}\d)/gi;

const SIG_EMAIL_RE = /([\w.+-]+@[\w.-]+\.[a-z]{2,})/i;

function extractFromSignature(text) {
  if (!text) return { name: '', phone: '', email: '' };

  const lines = text.split('\n');

  let greetingIdx = -1;
  for (let i = lines.length - 1; i >= 0; i--) {
    if (EXIT_GREETING_RE.test(lines[i])) {
      greetingIdx = i;
      break;
    }
  }

  if (greetingIdx === -1) return { name: '', phone: '', email: '' };

  const sigLines = lines.slice(greetingIdx + 1);

  let name = '';
  for (const raw of sigLines) {
    const line = raw.trim();
    if (!line) continue;
    if (SIG_NOISE_RE.test(line)) continue;
    if (/^\d{2,}/.test(line)) continue;
    if (/@/.test(line)) continue;
    if (/^https?:\/\//i.test(line)) continue;
    if (/^[+\d\s().-]+$/.test(line)) continue;

    let candidate = line
      .replace(/^(?:Mr\.?|Mrs\.?|Ms\.?|Miss|Dr\.?|Prof\.?)\s*/i, '')
      .replace(/[|–—·•].*$/, '')
      .trim();

    if (candidate.length >= 2 && candidate.length <= 60 &&
        /^[\p{L}\s'.-]+$/u.test(candidate) &&
        candidate.split(/\s+/).length >= 1 && candidate.split(/\s+/).length <= 6) {
      const titleMatch = line.match(/^(Mr\.?|Mrs\.?|Ms\.?|Miss|Dr\.?|Prof\.?)\s*/i);
      name = titleMatch ? titleMatch[0].trim() + ' ' + candidate : candidate;
      break;
    }
  }

  const sigBlock = sigLines.join('\n');
  let phone = '';
  const phoneMatches = [];
  let pm;
  const phoneRe = new RegExp(PHONE_RE.source, PHONE_RE.flags);
  while ((pm = phoneRe.exec(sigBlock)) !== null) {
    const cleaned = pm[1].replace(/[^+\d]/g, '');
    if (cleaned.length >= 7 && cleaned.length <= 15) {
      phoneMatches.push(pm[1].trim());
    }
  }
  if (phoneMatches.length) {
    const mobile = phoneMatches.find(p => /(?:^07|^\+?\d{1,3}\s*7)/i.test(p.replace(/[^+\d]/g, '')));
    phone = mobile || phoneMatches[0];
  }

  let email = '';
  const emailMatch = sigBlock.match(SIG_EMAIL_RE);
  if (emailMatch) email = emailMatch[1];

  return { name, phone, email };
}

// ================================================================
// GREETING INTRO EXTRACTION
// ================================================================

const COMMON_WORDS = new Set([
  'a','about','after','all','also','an','and','any','are','as','at','back','be',
  'been','but','by','can','come','could','do','down','each','even','find','first',
  'for','from','get','give','go','going','good','got','great','had','has','have',
  'he','her','here','him','his','how','i','if','in','into','is','it','its','just',
  'know','let','like','look','looking','lot','make','me','more','much','my','new',
  'no','not','now','of','off','on','one','only','or','other','our','out','over',
  'own','really','right','said','say','see','she','so','some','still','such',
  'sure','take','than','that','the','their','them','then','there','these','they',
  'think','this','those','through','time','to','too','try','two','up','us','use',
  'very','want','was','way','we','well','were','what','when','where','which',
  'while','who','will','with','wonder','wondering','work','would','writing','year',
  'you','your','emailing','enquiring','contacting','reaching','planning','hoping',
  'interested','happy','delighted','pleased','sorry','afraid','able','unable',
]);

function looksLikeName(str) {
  if (!str || str.length < 2 || str.length > 40) return false;
  if (!/^[A-Z\u00C0-\u024F]/.test(str)) return false;
  if (!/^[\p{L}\s'.-]+$/u.test(str)) return false;
  const firstWord = str.split(/\s+/)[0].toLowerCase();
  if (COMMON_WORDS.has(firstWord)) return false;
  const words = str.split(/\s+/);
  if (words.length < 1 || words.length > 5) return false;
  return true;
}

function extractFromGreeting(text) {
  if (!text) return { name: '' };
  const intro = text.slice(0, 500);

  const p1 = intro.match(/[Mm]y\s+name\s+is\s+([\p{L}][\p{L}\s'.-]{1,39}?)(?:\s*[,.\n;]|\s+and\b|\s+from\b)/u);
  if (p1 && looksLikeName(p1[1].trim())) return { name: p1[1].trim() };

  const p2 = intro.match(/I[''\u2019]m\s+([\p{L}][\p{L}\s'.-]{1,39}?)(?:\s*[,.\n;]|\s+and\b|\s+from\b)/u)
          || intro.match(/I\s+am\s+([\p{L}][\p{L}\s'.-]{1,39}?)(?:\s*[,.\n;]|\s+and\b|\s+from\b)/u);
  if (p2 && looksLikeName(p2[1].trim())) return { name: p2[1].trim() };

  const p3 = intro.match(/[Tt]his\s+is\s+([\p{L}][\p{L}\s'.-]{1,39}?)(?:\s*[,.\n;]|\s+from\b|\s+at\b|\s+with\b)/u);
  if (p3 && looksLikeName(p3[1].trim())) return { name: p3[1].trim() };

  return { name: '' };
}

// ================================================================
// INLINE CONTEXTUAL PHONE EXTRACTION
// ================================================================

function extractInlinePhone(text) {
  if (!text) return '';

  const patterns = [
    /(?:call|reach|contact|text|ring|get)\s+me\s+(?:on|at)\s*:?\s*([+\d][\d\s().-]{5,}\d)/i,
    /my\s+(?:number|phone|mobile|cell|tel|telephone|mob|direct\s+(?:number|line))\s+(?:is|:)\s*([+\d][\d\s().-]{5,}\d)/i,
    /I[\u2019'']\s*m\s+on\s+([+\d][\d\s().-]{5,}\d)/i,
    /I\s+am\s+on\s+([+\d][\d\s().-]{5,}\d)/i,
    /you\s+can\s+(?:get|reach|contact|call)\s+me\s+(?:on|at)\s*:?\s*([+\d][\d\s().-]{5,}\d)/i,
    /best\s+to\s+(?:call|ring|text|reach\s+me\s+on)\s*:?\s*([+\d][\d\s().-]{5,}\d)/i,
  ];

  for (const re of patterns) {
    const m = text.match(re);
    if (m) {
      const cleaned = m[1].replace(/[^+\d]/g, '');
      if (cleaned.length >= 7 && cleaned.length <= 15) {
        return m[1].trim();
      }
    }
  }
  return '';
}

// ---------- CLIENT INFO EXTRACTION ----------
// Priority: Form fields > Signature > Greeting intro > Inline phone > Fallback email
// EMAIL RULE: Sender address ALWAYS wins for non-form messages.
function extractClientInfo(text, fallbackEmail, isFormMessage) {
  const t = text || '';
  const pick = re => { const m=t.match(re); return m?m[1].trim():''; };

  const info = {
    name:      pick(/(?:^|\n)\s*(?:From|What'?s your name\??|Name)\s*[:\n]\s*([^\n]+)/i),
    email:     pick(/(?:E-?mail|EMAIL)\s*[:\n]\s*([\w.+-]+@[\w.-]+)/i),
    phone:     pick(/(?:Telephone|PHONE|Phone)\s*[:\n]\s*([+\d\s()-]{6,})/i),
    event_type:pick(/(?:Type of event|What kind of event[^\n?]*\??)\s*[:\n]\s*([^\n]+)/i),
    event_date:pick(/(?:Date(?: of your event)?|DATE OF YOUR EVENT|Have you set a date\??)\s*[:\n]\s*([^\n]+)/i),
    location:  pick(/(?:Postcode\/?location|Where will your event be(?:\s+held)?\??|Location|Venue)\s*[:\n]\s*([^\n]+)/i),
    guests:    pick(/(?:How many (?:G|g)uests\??|Guests)\s*[:\n]\s*([^\n]+)/i),
    budget:    pick(/Budget\s*[:\n]\s*([^\n]+)/i),
    sent_from: pick(/(?:Sent from|Where did you find us\??)\s*[:\n]\s*([^\n]+)/i),
  };

  const sig = extractFromSignature(t);
  if (!info.name  && sig.name)  info.name  = sig.name;
  if (!info.phone && sig.phone) info.phone = sig.phone;
  if (!info.email && sig.email && isFormMessage) info.email = sig.email;

  if (!info.name) {
    const greeting = extractFromGreeting(t);
    if (greeting.name) info.name = greeting.name;
  }

  if (!info.phone) {
    const inlinePhone = extractInlinePhone(t);
    if (inlinePhone) info.phone = inlinePhone;
  }

  if (!info.email && fallbackEmail) info.email = fallbackEmail;

  return info;
}

function extractClientMessageOnly(text) {
  const m = text.match(/(?:^|\n)\s*(?:Message|What are you planning\??|Mobile message[^\n]*)\s*[:\n]\s*([\s\S]+?)(?:\n\s*---|\n\s*This email is a system notification|\n\s*Where did you find us\??|$)/i);
  return m ? m[1].trim() : text.trim();
}

// ---------- AI MATCHING ----------
function matchAiReplies(messages, lastSentList, lastPlaceList) {
  const assignments = [];
  const used = new Set();
  for (let i=0;i<lastSentList.length;i++) {
    const ai = normalizeForMatch(lastSentList[i]);
    if (!ai) continue;
    const head = ai.slice(0,200);
    let best = {idx:-1, score:0};
    for (let j=0;j<messages.length;j++) {
      if (used.has(j)) continue;
      const body = normalizeForMatch(messages[j].bodyText);
      if (!body) continue;
      let score = 0;
      if (body.includes(head)) score = 1;
      else score = jaccardTokenSet(ai, body);
      if (score > best.score) best = {idx:j, score};
    }
    if (best.idx>=0 && best.score>=0.75) {
      used.add(best.idx);
      assignments.push({aiIndex:i, messageIndex:best.idx, score:best.score, followUp:lastPlaceList[i]||null});
    }
  }
  return assignments;
}

// ---------- CLASSIFY ----------
// Priority: Form sender → AI match → Internal sender → External (from_client)
function classifyAll(messages, aiAssignments) {
  const aiMap = new Map(aiAssignments.map(a=>[a.messageIndex, a]));
  return messages.map((m,idx) => {
    if (isEnquiryFormSender(m.fromAddress))
      return {index:idx, from:m.fromAddress, label:'from_client', followUp:null, reason:'enquiry_form_sender', dateUTC:m.date?m.date.toISOString():null};
    if (aiMap.has(idx)) {
      const a = aiMap.get(idx);
      return {index:idx, from:m.fromAddress, label:'reply_AI', followUp:a.followUp, reason:'matched_last_sent', dateUTC:m.date?m.date.toISOString():null};
    }
    if (isInternalSender(m.fromAddress))
      return {index:idx, from:m.fromAddress, label:'reply_manual', followUp:null, reason:isAiSender(m.fromAddress)?'ai_address_unmatched':'internal_sender', dateUTC:m.date?m.date.toISOString():null};
    return {index:idx, from:m.fromAddress, label:'from_client', followUp:null, reason:'external_sender', dateUTC:m.date?m.date.toISOString():null};
  });
}

// ---------- DEDUPE ----------
function dedupeInbound(messages, inbound) {
  if (!inbound) return messages;
  const inboundNorm = normalizeForMatch(stripHtmlToText(inbound.bodyContent||'')).slice(0,400);
  const inboundFrom = addrOf(inbound.fromAddress);
  const inboundTs = inbound.sentDateTime ? new Date(inbound.sentDateTime).getTime() : null;
  return messages.filter(m => {
    if (m.fromAddress !== inboundFrom) return true;
    if (inboundTs && m.date && Math.abs(m.date.getTime()-inboundTs) > 5*60*1000) return true;
    const mNorm = normalizeForMatch(m.bodyText).slice(0,400);
    if (!inboundNorm || !mNorm) return true;
    return !(mNorm.includes(inboundNorm.slice(0,150)) || inboundNorm.includes(mNorm.slice(0,150)));
  });
}

// ---------- RENDER (conversation only) ----------
function renderConversation(messages, classifications) {
  if (!messages.length) return '(no conversation messages)';
  const lines = [];
  messages.forEach((m,i) => {
    const c = classifications[i];
    const isForm = isEnquiryFormSender(m.fromAddress);
    const body = isForm ? extractClientMessageOnly(m.bodyText) : m.bodyText;
    const ts = m.date ? formatUK(m.date) : (m.dateRaw||'unknown');
    const fu = c.followUp ? ` {${c.followUp}}` : '';
    lines.push(`[${ts} UK] <${m.fromAddress}> [${c.label}]${fu}`);
    lines.push(body.trim());
    lines.push('');
  });
  return lines.join('\n').trim();
}

function formatUK(d) {
  const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const pad=n=>String(n).padStart(2,'0');
  const y=d.getUTCFullYear(), mo=d.getUTCMonth(), da=d.getUTCDate(), h=d.getUTCHours(), mi=d.getUTCMinutes();
  const utcMs = Date.UTC(y,mo,da,h,mi);
  const lastSun=(yr,m)=>{const dt=new Date(Date.UTC(yr,m+1,0));return dt.getUTCDate()-dt.getUTCDay();};
  const bstStart=Date.UTC(y,2,lastSun(y,2),1,0), bstEnd=Date.UTC(y,9,lastSun(y,9),1,0);
  const offset = (utcMs>=bstStart && utcMs<bstEnd) ? 60 : 0;
  const local = new Date(utcMs + offset*60000);
  return `${pad(local.getUTCDate())} ${months[local.getUTCMonth()]} ${local.getUTCFullYear()} ${pad(local.getUTCHours())}:${pad(local.getUTCMinutes())}`;
}

// ---------- MAIN ----------
const results = [];
for (const item of items) {
  const j = item.json;
  const warnings = [];

  const inboundMsg = {
    fromAddress: addrOf(j.fromAddress),
    date: j.sentDateTime?new Date(j.sentDateTime):null,
    bodyHtml: j.bodyContent||'',
    bodyText: stripHtmlToText(j.bodyContent||''),
    subject: j.subject||'',
  };

  let threadMsgs = parseThreadHistory(j.threadHistory||'');
  threadMsgs = dedupeInbound(threadMsgs, j);

  const hasInbound = threadMsgs.some(m =>
    m.fromAddress===inboundMsg.fromAddress &&
    Math.abs((m.date?.getTime()||0)-(inboundMsg.date?.getTime()||0)) < 5*60*1000
  );
  if (!hasInbound) threadMsgs.push(inboundMsg);

  threadMsgs.sort((a,b)=>(a.date?.getTime()||0)-(b.date?.getTime()||0));

  // AI matching — split last_sent_message on -NEXT- delimiter, last_place on comma
  const lastSent = Array.isArray(j.last_sent_message) ? j.last_sent_message
                 : (typeof j.last_sent_message==='string' && j.last_sent_message.trim()
                    ? j.last_sent_message.split(/\s*-NEXT-\s*/i).map(s=>s.trim()).filter(Boolean)
                    : []);
  const lastPlace = Array.isArray(j.last_place_in_follow_up) ? j.last_place_in_follow_up
                  : (typeof j.last_place_in_follow_up==='string' && j.last_place_in_follow_up.trim()
                     ? j.last_place_in_follow_up.split(/\s*,\s*/).map(s=>s.trim()).filter(Boolean)
                     : []);
  const aiAssignments = matchAiReplies(threadMsgs, lastSent, lastPlace);
  if (lastSent.length && aiAssignments.length < lastSent.length) warnings.push(`Only matched ${aiAssignments.length}/${lastSent.length} AI replies`);

  const classifications = classifyAll(threadMsgs, aiAssignments);

  // Client information — form extraction first, then first client message
  // EMAIL RULE: Sender address ALWAYS wins for non-form messages.
  let clientInfo = {name:'',email:'',phone:'',event_type:'',event_date:'',location:'',guests:'',budget:'',sent_from:''};
  const formMsg = threadMsgs.find(m => isEnquiryFormSender(m.fromAddress));
  if (formMsg) {
    clientInfo = extractClientInfo(formMsg.bodyText, '', true);
  } else {
    const firstClientIdx = classifications.findIndex(c=>c.label==='from_client');
    if (firstClientIdx>=0) {
      const m = threadMsgs[firstClientIdx];
      const extracted = extractClientInfo(m.bodyText, m.fromAddress, false);
      clientInfo = {...clientInfo, ...extracted, email: m.fromAddress};
    }
  }

  // Derive email_reply_to — always populated, never a form sender address
  const senderAddr = addrOf(j.fromAddress);
  let emailReplyTo;
  if (isEnquiryFormSender(senderAddr)) {
    // Form: use extracted client email, fall back to form sender address
    emailReplyTo = clientInfo.email || senderAddr;
  } else {
    // Non-form: always the original sender
    emailReplyTo = senderAddr;
  }

  const rendered = renderConversation(threadMsgs, classifications);
  const render_hash = sha256(rendered);

  results.push({
    json: {
      rendered,
      email_reply_to: emailReplyTo,
      client_information: {
        name:        clientInfo.name        || null,
        email:       clientInfo.email       || null,
        phone:       clientInfo.phone       || null,
        event_type:  clientInfo.event_type  || null,
        event_date:  clientInfo.event_date  || null,
        location:    clientInfo.location    || null,
        guests:      clientInfo.guests      || null,
        budget:      clientInfo.budget      || null,
        sent_from:   clientInfo.sent_from   || null,
      },
      metadata: {
        subject: j.subject || null,
        found: j.found === true || String(j.found).toLowerCase() === 'true',
        added_to_whatsapp: j.added_to_whatsapp === true || String(j.added_to_whatsapp).toLowerCase() === 'true',
        messageCount: threadMsgs.length,
        classifications,
        id: j.id || null,
        conversationId: j.conversationId || null,
        render_hash,
        warnings,
      },
    },
  });
}
return results;

// ============================================================================
// n8n Code node body: "Build Engine Payload"
// ----------------------------------------------------------------------------
// The tap node the engine hangs off ("Combine all Email Data") is an EMPTY Set
// node, so "POST to Engine" was posting whatever $json happened to be. The
// engine's intake contract is:
//
//   { thread_id, messages: [{ message_id, from, to[], date_iso, subject, body }] }
//
// Anything else is stored in inbound_raw and never reaches the pipeline. This
// node builds that contract from the Gmail data already in the branch.
//
// Bodies are handed over RAW and uncleaned on purpose: app/lib/engine/normalize.ts
// is a faithful port of the workflow's own cleaner and runs on our side, so
// cleaning here would only give us two cleaners to keep in step.
//
// Lives in the repo (not only inside n8n) so it can be tested without n8n --
// see scripts/test-engine-payload.mjs. Installed by scripts/install-payload-builder.mjs.
//
// Sources, in order of preference:
//   $('Get a thread2')       full Gmail thread resource -> ids, dates, subjects
//   $('Normalize Data')      original_email + thread_history (bodies only)
//   $('Conversational Renderer') / $('Determine if Order')  -> carried as context
// ============================================================================

/** Safely read a node's output; returns null when the node did not run. */
function nodeJson(name) {
  try {
    const item = $(name).item;
    return item && item.json ? item.json : null;
  } catch (e) {
    return null;
  }
}
/** Same, but the node's full item list (for multi-message nodes). */
function nodeAll(name) {
  try {
    return $(name).all().map((i) => i.json);
  } catch (e) {
    return [];
  }
}

function decodeB64(data) {
  if (!data) return '';
  try {
    return Buffer.from(String(data).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8');
  } catch (e) {
    return '';
  }
}

/** Pull the best body out of a Gmail message payload (prefers text/plain). */
function extractBody(msg) {
  if (!msg) return '';
  if (typeof msg.text === 'string' && msg.text.trim()) return msg.text;
  const walk = (part) => {
    if (!part) return '';
    if (Array.isArray(part.parts)) {
      const plain = part.parts.find((p) => p.mimeType === 'text/plain');
      if (plain && plain.body && plain.body.data) return decodeB64(plain.body.data);
      const html = part.parts.find((p) => p.mimeType === 'text/html');
      if (html && html.body && html.body.data) return decodeB64(html.body.data);
      for (const p of part.parts) {
        const nested = walk(p);
        if (nested) return nested;
      }
    }
    if (part.body && part.body.data) return decodeB64(part.body.data);
    return '';
  };
  const body = walk(msg.payload);
  if (body) return body;
  if (typeof msg.snippet === 'string') return msg.snippet;
  return '';
}

// Header names n8n's Gmail node flattens straight onto the message item, in
// their wire casing. Everything here is looked up case-insensitively.
const FLAT_HEADER_KEYS = [
  'From', 'To', 'Cc', 'Bcc', 'Subject', 'Date', 'Message-ID', 'In-Reply-To',
  'References', 'Reply-To', 'Content-Type', 'MIME-Version',
];

function headerMap(msg) {
  const out = {};
  if (!msg) return out;

  const hs = (msg.payload && msg.payload.headers) || [];
  for (const h of hs) if (h && h.name) out[String(h.name).toLowerCase()] = h.value;

  if (msg.headers && typeof msg.headers === 'object') {
    for (const [k, v] of Object.entries(msg.headers)) if (out[k.toLowerCase()] === undefined) out[k.toLowerCase()] = v;
  }

  // The case that actually bit us. "Get a thread" returns messages whose
  // payload has NO headers array (it holds only the MIME parts) and no
  // msg.headers object - the headers are flattened onto the item itself as
  // "From", "To", "Subject", "Date", "Message-ID". Reading only msg.from /
  // msg.subject therefore yielded "" for every real message, so every thread
  // reached the engine with no sender and no subject. The bodies arrived fine,
  // which is why it looked like it was working: three live threads were
  // classified with the sender and subject blanked out.
  for (const k of FLAT_HEADER_KEYS) {
    const lower = k.toLowerCase();
    if (out[lower] !== undefined) continue;
    if (msg[k] !== undefined && msg[k] !== null && msg[k] !== '') out[lower] = msg[k];
    else if (msg[lower] !== undefined && msg[lower] !== null && msg[lower] !== '') out[lower] = msg[lower];
  }
  return out;
}

/** "Ben <ben@x.com>" | {value:[{address}]} | "ben@x.com" -> "ben@x.com" */
function addrOf(v) {
  if (!v) return '';
  if (Array.isArray(v)) return addrOf(v[0]);
  if (typeof v === 'object') {
    if (v.address) return String(v.address).toLowerCase();
    if (v.email) return String(v.email).toLowerCase();
    if (v.value) return addrOf(v.value);
    return '';
  }
  const s = String(v);
  const m = s.match(/<([^>]+)>/);
  return (m ? m[1] : s).trim().toLowerCase();
}

/** Split a To/Cc header into addresses. */
function addrList(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v.map(addrOf).filter(Boolean);
  return String(v)
    .split(',')
    .map((s) => addrOf(s))
    .filter(Boolean);
}

function toIso(msg, headers) {
  const raw = msg && (msg.internalDate || msg.date);
  if (raw) {
    const n = Number(raw);
    const d = Number.isFinite(n) && String(raw).length >= 10 ? new Date(n) : new Date(raw);
    if (!isNaN(d.getTime())) return d.toISOString();
  }
  if (headers && headers.date) {
    const d = new Date(headers.date);
    if (!isNaN(d.getTime())) return d.toISOString();
  }
  return new Date().toISOString();
}

const SPARTAN_DOMAINS = ['@spartancrew.co.uk'];
const isSpartan = (from) => SPARTAN_DOMAINS.some((d) => String(from || '').toLowerCase().includes(d));

/** One Gmail message resource -> one engine ThreadMessage. */
function toThreadMessage(msg) {
  const h = headerMap(msg);
  const from = addrOf(msg.from || h.from);
  return {
    message_id: String(msg.id || h['message-id'] || ''),
    from,
    to: addrList(msg.to || h.to),
    date_iso: toIso(msg, h),
    subject: String((msg.subject !== undefined ? msg.subject : h.subject) || ''),
    body: extractBody(msg),
    is_from_spartan: isSpartan(from),
  };
}

// ---------------------------------------------------------------- build
const norm = nodeJson('Normalize Data') || {};
const original = norm.original_email || {};
const threadNode = nodeJson('Get a thread2') || {};
// The classifier node has been rebuilt more than once - it was "Determine if
// Order" (+ Failsafe) as a plain openAi node, and is now an AI Agent feeding
// "Parse Job Determinism Output", with gpt-5 primary and opus 4.6 as fallback.
// nodeJson swallows a missing node, so a rename does not break the run - it just
// silently drops the verdict from the durable record, which is the one field that
// lets anyone compare n8n's judgement against the engine's. Try the current names
// first and keep the old ones so this works against either shape.
const VERDICT_NODES = [
  'Parse Job Determinism Output',
  'AI Agent',
  'Determine if Order',
  'Determine if Order Failsafe',
];
let verdict = {};
let verdict_source = null;
for (const name of VERDICT_NODES) {
  const j = nodeJson(name);
  if (j) { verdict = j; verdict_source = name; break; }
}
const renderer = nodeJson('Conversational Renderer') || {};

const thread_id = String(threadNode.id || original.thread_id || norm.thread_id || $json.threadId || $json.thread_id || '').trim();

// Prefer the full Gmail thread; fall back to the merged hydrated items, then to
// the single original email. Never emit zero messages when we have any content.
let source = Array.isArray(threadNode.messages) && threadNode.messages.length ? threadNode.messages : null;
if (!source) {
  const merged = nodeAll('Merge1').filter((m) => m && (m.id || m.payload || m.text));
  if (merged.length) source = merged;
}

let messages = (source || []).map(toThreadMessage).filter((m) => m.body && m.body.trim());

if (!messages.length && (original.body || original.email_id)) {
  messages = [
    {
      message_id: String(original.email_id || ''),
      from: addrOf(original.from),
      to: [],
      date_iso: new Date().toISOString(),
      subject: String(original.subject || ''),
      body: String(original.body || ''),
      is_from_spartan: isSpartan(original.from),
    },
  ];
}

// The cleaned history Normalize Data produced is bodies-only (no ids or dates),
// so it cannot become a ThreadMessage. Carry it as context rather than drop it.
const history_text = (norm.thread_history && Array.isArray(norm.thread_history.messages))
  ? norm.thread_history.messages
  : [];

messages.sort((a, b) => Date.parse(a.date_iso) - Date.parse(b.date_iso));

return [
  {
    json: {
      thread_id,
      messages,
      // Everything below is context the engine records for transparency; the
      // contract above is what drives the pipeline.
      n8n: {
        workflow: 'Email SamurAI v3.4 Spartan Crew Bookings',
        latest_message_id: String(original.email_id || (messages.length ? messages[messages.length - 1].message_id : '')),
        // The old openAi node wrapped its answer in message/content; the parse
        // node emits the fields directly (is_job, type_job, job_summary). Fall
        // back to the whole object rather than recording null for a shape we did
        // not anticipate - this field is pure transparency, so keeping too much
        // costs nothing and keeping nothing costs the audit trail.
        verdict: verdict.message || verdict.content || verdict.text || verdict.output ||
          (verdict_source && Object.keys(verdict).length ? verdict : null),
        verdict_source: verdict_source,
        client_information: renderer.client_information || null,
        render_hash: (renderer.metadata && renderer.metadata.render_hash) || null,
        classifications: (renderer.metadata && renderer.metadata.classifications) || null,
        // Read these off the Dedupe Claim node, NOT $json. At this point in the
        // branch $json is the classifier's item, which never carries them, so
        // reading $json silently reported found:false for every message.
        dedupe: (function () {
          const d = nodeJson('Dedupe Claim') || $json || {};
          return {
            found: d.found === true,
            first_seen: d.first_seen === true,
            thread_first_seen: d.thread_first_seen === true,
            thread_message_count: d.thread_message_count || null,
            degraded: d.degraded || null,
          };
        })(),
        history_text,
        message_count: messages.length,
      },
    },
  },
];

